Database Engine: PostgreSQL (Supabase). Schema: AlphaMap Core DB.

Flawed query:
SELECT s.name, fr.round_type, fr.amount_raised FROM startups s, funding_rounds fr;

Database Engine: PostgreSQL (Supabase). Schema: AlphaMap Core DB.

Flawed query:
SELECT id, name, funding_amount FROM startups ORDER BY funding_amount DESC;

Database Engine: PostgreSQL (Supabase). Schema: AlphaMap Core DB.

Flawed query:
SELECT d.id, d.company_name, d.amount_raised AS deals_amount, fr.amount_raised AS rounds_amount FROM deals d JOIN funding_rounds fr ON fr.startup_id = d.startup_id AND fr.announcement_date = d.deal_date WHERE d.amount_raised != fr.amount_raised;

Database Engine: PostgreSQL (Supabase). Schema: AlphaMap Core DB.

Flawed query:
SELECT s.id, s.name, (SELECT ash.score FROM alphamap_score_history ash WHERE ash.startup_id = s.id ORDER BY ash.snapshot_date DESC LIMIT 1) AS latest_score FROM startups s;

Database Engine: PostgreSQL (Supabase). Schema: AlphaMap Core DB.

Flawed query:
SELECT s.name, fr.round_type, fr.announcement_date FROM startups s JOIN funding_rounds fr ON fr.startup_id = s.id WHERE fr.announcement_date = (SELECT MAX(announcement_date) FROM funding_rounds WHERE startup_id = s.id);

Database Engine: PostgreSQL (Supabase). Schema: AlphaMap Core DB.

Flawed query:
SELECT s.industry, s.name, COUNT(fr.id) AS round_count FROM startups s JOIN funding_rounds fr ON fr.startup_id = s.id GROUP BY s.industry;

